export const catalogs=Object.fromEntries(Object.entries(rows).map(([l,r])=>[l,Object.fromEntries(keys.map((k,i)=>[k,r[i]]))]));
export function t(key,vars={}){let s=catalogs[lang][key]??key;return s.replace(/\{(\w+)\}/g,(_,k)=>String(vars[k]??''));}
export function translateError(error){const s=error.message;for(const key of keys.filter(k=>k.startsWith('error'))){if(s===catalogs.ko[key])return t(key);}
 let m;if((m=s.match(/^레코드 (\d+): 닫는 인용부호/)))return t('errorQuoteClosed',{n:m[1]});if((m=s.match(/^레코드 (\d+): 셀 중간/)))return t('errorQuoteMiddle',{n:m[1]});if((m=s.match(/^레코드 (\d+): 닫히지/)))return t('errorQuoteOpen',{n:m[1]});if((m=s.match(/^레코드 (\d+): (\d+)열입니다. 헤더의 (\d+)/)))return t('errorWidth',{n:m[1],actual:m[2],expected:m[3]});return s;}
export function languageMenu(){return `<label class="check">🌐 <select id="language" aria-label="Language">${Object.entries(languages).map(([k,v])=>`<option value="${k}" ${k===lang?'selected':''}>${v}</option>`).join('')}</select></label>`;}
export function bindLanguage(){document.getElementById('language').onchange=e=>{location.href=new URL(e.target.value==='ko'?'./':e.target.value+'/',document.baseURI).href;};document.documentElement.lang=lang;}
